import type { UserRole, UserRow, UserStatus } from "../../types";

// ---------------------------------------------------------------------------
// Создание пользователя (по умолчанию status = 'pending', ждёт подтверждения
// учительницей)
// ---------------------------------------------------------------------------
export interface CreateUserInput {
  firstName: string;
  lastName: string;
  email: string;
  passwordHash: string;
  role: UserRole;
  status?: UserStatus;
  classId: string | null;
}

export async function createUser(
  db: D1Database,
  input: CreateUserInput
): Promise<UserRow> {
  const id = crypto.randomUUID();
  const status = input.status ?? "pending";

  await db
    .prepare(
      `INSERT INTO users (id, first_name, last_name, email, password_hash, role, status, class_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
    )
    .bind(
      id,
      input.firstName,
      input.lastName,
      input.email.toLowerCase(),
      input.passwordHash,
      input.role,
      status,
      input.classId
    )
    .run();

  const user = await getUserById(db, id);
  if (!user) {
    throw new Error("Не удалось создать пользователя");
  }
  return user;
}

// ---------------------------------------------------------------------------
// Поиск пользователя
// ---------------------------------------------------------------------------
export async function getUserByEmail(
  db: D1Database,
  email: string
): Promise<UserRow | null> {
  const row = await db
    .prepare("SELECT * FROM users WHERE email = ?")
    .bind(email.toLowerCase())
    .first<UserRow>();

  return row ?? null;
}

export async function getUserById(
  db: D1Database,
  id: string
): Promise<UserRow | null> {
  const row = await db
    .prepare("SELECT * FROM users WHERE id = ?")
    .bind(id)
    .first<UserRow>();

  return row ?? null;
}

// ---------------------------------------------------------------------------
// Списки пользователей (для админ-панели учительницы)
// ---------------------------------------------------------------------------
export async function listUsersByStatus(
  db: D1Database,
  status: UserStatus
): Promise<UserRow[]> {
  const { results } = await db
    .prepare("SELECT * FROM users WHERE status = ? ORDER BY created_at ASC")
    .bind(status)
    .all<UserRow>();

  return results ?? [];
}

export async function listPendingUsers(db: D1Database): Promise<UserRow[]> {
  return listUsersByStatus(db, "pending");
}

export async function listStudentsByClass(
  db: D1Database,
  classId: string
): Promise<UserRow[]> {
  const { results } = await db
    .prepare(
      `SELECT * FROM users
       WHERE class_id = ? AND role = 'student' AND status = 'approved'
       ORDER BY last_name ASC, first_name ASC`
    )
    .bind(classId)
    .all<UserRow>();

  return results ?? [];
}

// ---------------------------------------------------------------------------
// Изменение статуса заявки (approved / rejected)
// ---------------------------------------------------------------------------
export async function updateUserStatus(
  db: D1Database,
  id: string,
  status: UserStatus
): Promise<void> {
  await db
    .prepare("UPDATE users SET status = ? WHERE id = ?")
    .bind(status, id)
    .run();
}

export async function deleteUser(db: D1Database, id: string): Promise<void> {
  await db.prepare("DELETE FROM users WHERE id = ?").bind(id).run();
}
